parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "remitente": {
      "type": "string",
      "enum": ["cliente", "proveedor", "otro"]
    },
    "destino": {
      "type": "string",
      "enum": ["florianopolis", "pipa", "general"]
    },
    "tema": {
      "type": "string",
      "enum": [
        "nomunity", "contacto", "fechas", "alojamiento", "precio_pagos",
        "que_incluye", "seguro", "inscripcion", "trabajo_remoto",
        "documentacion", "cancelacion", "convivencia",
        "propuesta_comercial", "pagos_facturas", "otro"
      ]
    },
    "accion": {
      "type": "string",
      "enum": ["borrador", "acuse", "derivado"]
    },
    "ids_respuesta": {
      "type": "string",
      "description": "Ids de las filas usadas, separados por coma. Vacío si no se usó ninguna."
    },
    "respuesta_generada": {
      "type": "string",
      "description": "Texto completo del mail de respuesta. Vacío si no corresponde responder."
    },
    "observaciones": {
      "type": "string",
      "description": "Nota breve para quien revisa el borrador."
    }
  },
  "required": [
    "remitente", "destino", "tema", "accion",
    "ids_respuesta", "respuesta_generada", "observaciones"
  ],
  "additionalProperties": false
}

